import logging
import uuid
import traceback

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
        except Exception:
            reference = uuid.uuid4().hex[:12]
            logger.error(
                "Order failed for user=%s item=%s quantity=%s ref=%s\n%s",
                user,
                item,
                quantity,
                reference,
                traceback.format_exc(),
            )
            if is_admin:
                details = traceback.format_exc()
                return (
                    500,
                    f"An unexpected error occurred (ref: {reference}).\n\n{details}",
                )
            return (
                500,
                f"An unexpected error occurred. Please try again later or contact support (ref: {reference}).",
            )

        return (
            200,
            f"Thank you {user}! Your order for {quantity} x {item} has been placed "
            f"(reservation id: {reservation_id}).",
        )
